    ALPHA: SECRET_ALPHA,
    BETA: SECRET_BETA,
    GAMMA: SECRET_GAMMA,
    DELTA: SECRET_DELTA,
}


def keyring(**overrides):
    ring = {node: [entry(1, secret)] for node, secret in SECRETS.items()}
    ring.update(overrides)
    return ring


