    self.assertEqual(
        self.reason_for(item, ring=future)[1], "not-yet-valid",
    )
    expired = {**RING, ALPHA: [entry(1, "22" * 32, not_after=275)]}
    self.assertEqual(
        self.reason_for(item, ring=expired)[1], "expired",
    )
